mapper.select:
select cache_value 
from bi_portal.sys_cache t
where 1=1
  and t.cache_type = #{type}
  and t.cache_key = #{key}
  and t.last_modify_time > DATE_ADD(NOW(), INTERVAL -${cacheDuration} MINUTE)

mapper.delete:
delete from bi_portal.sys_cache
where 1=1

 	and cache_type = #{type}


 	and cache_key = #{key}
